{"id":"fb08089e-93ca-4a00-88d8-2bd2727258bd","inserted_at":"2026-06-23T14:16:25.173989+00:00","updated_at":"2026-06-23T14:16:25.173989+00:00","type":"sql","name":"Untitled query","description":"","content":{"sql":"-- MIGRATION V17: FIX RPC PER INCLUDERE MEDIA\r\n\r\n-- 1. Aggiorniamo get_pois()\r\nDROP FUNCTION IF EXISTS get_pois();\r\n\r\nCREATE FUNCTION get_pois()\r\nRETURNS TABLE (\r\n    id UUID, name TEXT, category TEXT, layer_name TEXT, xp_reward INTEGER, checkin_radius INTEGER,\r\n    crowd_level INTEGER, has_water BOOLEAN, is_accessible BOOLEAN, alternative_poi_id UUID,\r\n    is_recommended BOOLEAN, latitude FLOAT8, longitude FLOAT8, p_iva TEXT,\r\n    image_url TEXT, description TEXT\r\n) AS $$\r\nBEGIN\r\n    RETURN QUERY\r\n    SELECT \r\n        p.id, p.name, p.category, p.layer_name, p.xp_reward, p.checkin_radius,\r\n        p.crowd_level, p.has_water, p.is_accessible, p.alternative_poi_id,\r\n        p.is_recommended, ST_Y(p.coords::geometry) as latitude, ST_X(p.coords::geometry) as longitude,\r\n        p.p_iva, p.image_url, p.description\r\n    FROM public.pois p\r\n    WHERE p.is_active = true\r\n    ORDER BY p.name ASC;\r\nEND;\r\n$$ LANGUAGE plpgsql SECURITY DEFINER;\r\n\r\n-- 2. Aggiorniamo get_pois_with_status()\r\nDROP FUNCTION IF EXISTS get_pois_with_status(UUID);\r\n\r\nCREATE OR REPLACE FUNCTION get_pois_with_status(p_profile_id UUID)\r\nRETURNS TABLE (\r\n    id UUID, name TEXT, category TEXT, layer_name TEXT, xp_reward INTEGER, checkin_radius INTEGER,\r\n    latitude FLOAT8, longitude FLOAT8, is_visited BOOLEAN, crowd_level INTEGER,\r\n    has_water BOOLEAN, is_accessible BOOLEAN, alternative_poi_id UUID,\r\n    is_recommended BOOLEAN, image_url TEXT, description TEXT\r\n) AS $$\r\nBEGIN\r\n    RETURN QUERY\r\n    SELECT \r\n        p.id, p.name, p.category, p.layer_name, p.xp_reward, p.checkin_radius,\r\n        ST_Y(p.coords::geometry) as latitude, ST_X(p.coords::geometry) as longitude,\r\n        EXISTS (\r\n            SELECT 1 FROM user_pois up WHERE up.poi_id = p.id AND up.profile_id = p_profile_id\r\n        ) as is_visited, p.crowd_level, p.has_water, p.is_accessible,\r\n        p.alternative_poi_id, p.is_recommended, p.image_url, p.description\r\n    FROM public.pois p\r\n    WHERE p.is_active = true;\r\nEND;\r\n$$ LANGUAGE plpgsql SECURITY DEFINER;","content_id":"fb08089e-93ca-4a00-88d8-2bd2727258bd","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
